1	// The host adapter generator of M3 (M3-4, S90, S91).
2	//
3	// In the poly arms the agent writes host.map.json as part of its solution: which instance and action each
4	// method of the host interface drives, and which fields each query reads. This generator validates the map
5	// against the host interface and the agent's poly module, and a map that names a machine, an instance, an
6	// action, a parameter, an argument or a field that does not exist is a failed build: every error is listed,
7	// and nothing is written. A valid map gives a TypeScript module, host.gen.ts, whose default export creates
8	// a fresh host over polyrun's kernel (M3-4): a method dispatches one action to one instance, a query reads
9	// the instance's flat state, and the network methods drive polyrun's message worker one message at a time
10	// (S89, S91). The machines are lowered beside it, in build/.
11	//
12	// Usage: node generate.mjs --map host.map.json --host host.ts --module <file.poly|file.ts> --out <dir> [--polyrun <specifier>]
13	import { mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
14	import { basename, join, resolve } from 'node:path';
15	import { pathToFileURL } from 'node:url';
16	import ts from 'typescript';
17	import { parse } from '@poly/lang';
18	import { readEmbedded } from '@poly/embed';
19	import { checkModule } from '@poly/core';
20	import { lowerMachine } from '@poly/lower';
21	
22	const NETWORK = ['inFlight', 'deliver', 'deliverAll'];
23	// The effect port (S95): the effects the system requested and has not had completed, and their completion.
24	const EFFECTS = ['pendingEffects', 'completeEffect'];
25	const ADAPTER = [...NETWORK, ...EFFECTS];
26	const RETURNS = ['verdict', 'state', 'nothing'];
27	const ARG = /^\$arg:([A-Za-z_$][\w$]*)$/;
28	
29	/** The members of `interface Host` in a host interface, with their parameter names, and whether it has the network API. */
30	export function readHost(text, file = 'host.ts') {
31	  const sf = ts.createSourceFile(file, text, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS);
32	  const members = new Map();
33	  let network = false;
34	  let found = false;
35	  for (const st of sf.statements) {
36	    if (!ts.isInterfaceDeclaration(st) || st.name.text !== 'Host') continue;
37	    found = true;
38	    network = (st.heritageClauses ?? []).some((h) => h.types.some((x) => x.expression.getText(sf) === 'Network'));
39	    for (const m of st.members) {
40	      if (!m.name || !ts.isIdentifier(m.name)) continue;
41	      const params = ts.isMethodSignature(m) ? m.parameters.map((p) => p.name.getText(sf)) : null;
42	      if (params) members.set(m.name.text, params);
43	    }
44	  }
45	  return { found, members, network };
46	}
47	
48	function loadModule(file) {
49	  const text = readFileSync(file, 'utf8');
50	  const parsed = file.endsWith('.ts') ? readEmbedded(text, file) : parse(text);
51	  if (!parsed.module) return { errors: parsed.diagnostics.map((d) => `the module does not parse: ${d.code} ${d.message}`) };
52	  const checked = checkModule(parsed.module);
53	  const errors = checked.diagnostics.filter((d) => d.severity === 'error').map((d) => `the module does not check: ${d.code} ${d.message}`);
54	  return { module: parsed.module, checked, errors };
55	}
56	
57	const keysOnly = (obj, allowed, where, errors) => {
58	  if (!obj || typeof obj !== 'object' || Array.isArray(obj)) { errors.push(`${where} is not an object`); return false; }
59	  for (const k of Object.keys(obj)) if (!allowed.includes(k)) errors.push(`${where} has an unknown key '${k}'`);
60	  return true;
61	};
62	
63	/**
64	 * Validates a map against the host interface and the module (S90). Returns the errors, empty when it is valid.
65	 * `host` is readHost's result; `module` the checked poly module.
66	 */
67	export function validate(map, host, module) {
68	  const errors = [];
69	  if (!keysOnly(map, ['$schema', 'module', 'instances', 'methods', 'queries'], 'host.map.json', errors)) return errors;
70	  for (const k of ['module', 'instances', 'methods', 'queries']) if (!(k in map)) errors.push(`host.map.json has no '${k}'`);
71	  if (errors.length) return errors;
72	  if (map.module !== module.name) errors.push(`module: the map names '${map.module}', and the module is '${module.name}'`);
73	  if (!host.found) errors.push('host.ts declares no interface Host');
74	  for (const reserved of ['__dispose', '__state', '__snapshot', '__restore']) if (host.members.has(reserved)) errors.push(`host.ts: the Host interface has a member '${reserved}', which the adapter reserves`);
75	  const machines = new Map(module.decls.filter((d) => d.kind === 'Machine').map((d) => [d.name, d]));
76	  const typeDecl = (name) => module.decls.find((d) => (d.kind === 'EnumDecl' || d.kind === 'TypeDecl') && d.name === name);
77	  const instances = map.instances ?? {};
78	  const methods = map.methods ?? {};
79	  const queries = map.queries ?? {};
80	
81	  // An instance name, or a family of instances a method creates, keyed by one of its arguments.
82	  for (const [name, inst] of Object.entries(instances)) {
83	    const where = `instances.${name}`;
84	    if (!keysOnly(inst, ['machine', 'createdBy', 'keyArgument', 'init'], where, errors)) continue;
85	    const m = machines.get(inst.machine);
86	    if (!m) { errors.push(`${where}: no machine '${inst.machine}' in module ${module.name}`); continue; }
87	    if ((inst.createdBy === undefined) !== (inst.keyArgument === undefined)) errors.push(`${where}: createdBy and keyArgument go together`);
88	    if (inst.createdBy !== undefined) {
89	      if (!(inst.createdBy in methods)) errors.push(`${where}: createdBy names no method '${inst.createdBy}'`);
90	      else if (methods[inst.createdBy].instance !== name) errors.push(`${where}: its createdBy method '${inst.createdBy}' targets '${methods[inst.createdBy].instance}', not this family`);
91	      const params = host.members.get(inst.createdBy);
92	      if (params && !params.includes(inst.keyArgument)) errors.push(`${where}: keyArgument '${inst.keyArgument}' is not an argument of ${inst.createdBy}(${params.join(', ')})`);
93	    }
94	    for (const [field, value] of Object.entries(inst.init ?? {})) {
95	      const f = m.fields.find((x) => x.name === field);
96	      if (!f) { errors.push(`${where}.init: ${m.name} has no field '${field}'`); continue; }
97	      const bad = initError(f.type, value, instances, typeDecl);
98	      if (bad) errors.push(`${where}.init.${field}: ${bad}`);
99	    }
100	  }
101	
102	  // The instance a method or query targets: a named instance, a family with the argument that keys it, or, as
103	  // "$arg:<argument>" with "machine", whichever instance created with the host the argument names.
104	  const target = (spec, where, params) => {
105	    const byArg = typeof spec.instance === 'string' ? ARG.exec(spec.instance) : null;
106	    if (byArg) {
107	      if (params && !params.includes(byArg[1])) errors.push(`${where}.instance: '${byArg[1]}' is not an argument of ${where.split('.')[1]}(${params.join(', ')})`);
108	      if (spec.key !== undefined) errors.push(`${where}: an instance named by an argument takes no key`);
109	      const m = machines.get(spec.machine);
110	      if (!m) { errors.push(`${where}: an instance named by an argument needs "machine", a machine of module ${module.name}${spec.machine ? `, not '${spec.machine}'` : ''}`); return null; }
111	      if (!Object.values(instances).some((x) => x.machine === spec.machine && x.createdBy === undefined)) errors.push(`${where}: no instance of ${spec.machine} is created with the host`);
112	      return m;
113	    }
114	    if (spec.machine !== undefined) errors.push(`${where}: "machine" goes only with an instance named by an argument`);
115	    const inst = instances[spec.instance];
116	    if (!inst) { errors.push(`${where}: no instance or family '${spec.instance}' in instances`); return null; }
117	    const keyed = inst.createdBy !== undefined;
118	    if (keyed && spec.key === undefined) errors.push(`${where}: '${spec.instance}' is a family, so the method names its key: "key": "$arg:<argument>"`);
119	    if (!keyed && spec.key !== undefined) errors.push(`${where}: '${spec.instance}' is one instance, so it takes no key`);
120	    if (spec.key !== undefined) {
121	      const a = ARG.exec(spec.key);
122	      if (!a) errors.push(`${where}.key: '${spec.key}' is not $arg:<argument>`);
123	      else if (params && !params.includes(a[1])) errors.push(`${where}.key: '${a[1]}' is not an argument of ${where.split('.')[1]}(${params.join(', ')})`);
124	    }
125	    return machines.get(inst.machine) ?? null;
126	  };
127	
128	  for (const [name, spec] of Object.entries(methods)) {
129	    const where = `methods.${name}`;
130	    if (!keysOnly(spec, ['instance', 'machine', 'key', 'action', 'params', 'returns'], where, errors)) continue;
131	    const params = host.members.get(name);
132	    if (!params) errors.push(`${where}: the Host interface has no method '${name}'`);
133	    if (NETWORK.includes(name)) errors.push(`${where}: '${name}' is the network API, which the adapter implements itself (S91)`);
134	    if (EFFECTS.includes(name)) errors.push(`${where}: '${name}' is the effect port, which the adapter implements itself (S95)`);
135	    if (spec.returns !== undefined && !RETURNS.includes(spec.returns)) errors.push(`${where}.returns: '${spec.returns}' is not one of ${RETURNS.join(', ')}`);
136	    const m = target(spec, where, params);
137	    if (!m) continue;
138	    const action = m.items.find((i) => i.kind === 'Action' && i.name === spec.action);
139	    if (!action) { errors.push(`${where}: ${m.name} has no action '${spec.action}'`); continue; }
140	    const given = spec.params ?? {};
141	    for (const p of action.params) if (!(p.name in given)) errors.push(`${where}.params: ${m.name}.${action.name} takes '${p.name}', which the map does not give`);
142	    for (const [p, v] of Object.entries(given)) {
143	      if (!action.params.some((x) => x.name === p)) errors.push(`${where}.params: ${m.name}.${action.name} has no parameter '${p}'`);
144	      const a = typeof v === 'string' ? ARG.exec(v) : null;
145	      if (a && params && !params.includes(a[1])) errors.push(`${where}.params.${p}: '${a[1]}' is not an argument of ${name}(${params.join(', ')})`);
146	    }
147	  }
148	
149	  for (const [name, spec] of Object.entries(queries)) {
150	    const where = `queries.${name}`;
151	    if (!keysOnly(spec, ['instance', 'machine', 'key', 'fields'], where, errors)) continue;
152	    const params = host.members.get(name);
153	    if (!params) errors.push(`${where}: the Host interface has no method '${name}'`);
154	    if (name in methods) errors.push(`${where}: '${name}' is mapped as a method too`);
155	    const m = target(spec, where, params);
156	    if (!m) continue;
157	    for (const [out, field] of Object.entries(spec.fields ?? {})) if (!m.fields.some((f) => f.name === field)) errors.push(`${where}.fields.${out}: ${m.name} has no field '${field}'`);
158	  }
159	
160	  // Every member of Host is driven by the map, except the network API, which the adapter implements.
161	  for (const name of host.members.keys()) {
162	    if (ADAPTER.includes(name)) continue;
163	    if (!(name in methods) && !(name in queries)) errors.push(`the Host interface's '${name}' is neither a method nor a query of the map`);
164	  }
165	  return errors;
166	}
167	
168	/** Why an initial value does not fit its field's type, or null. Only the types a configuration sets are taken. */
169	function initError(t, v, instances, typeDecl) {
170	  switch (t.kind) {
171	    case 'TBool': return typeof v === 'boolean' ? null : `${JSON.stringify(v)} is not a bool`;
172	    case 'TInt': return Number.isInteger(v) ? null : `${JSON.stringify(v)} is not an int`;
173	    case 'TString': return typeof v === 'string' ? null : `${JSON.stringify(v)} is not a string`;
174	    case 'TRange': return Number.isInteger(v) && v >= t.lo && v <= t.hi ? null : `${JSON.stringify(v)} is not in ${t.lo}..${t.hi}`;
175	    case 'TRef': {
176	      if (v === null) return null;
177	      const inst = instances[v];
178	      if (!inst || inst.createdBy !== undefined) return `${JSON.stringify(v)} is not an instance created with the host`;
179	      const want = t.machine[t.machine.length - 1];
180	      return inst.machine === want ? null : `${v} is a ${inst.machine}, not a ${want}`;
181	    }
182	    case 'TName': {
183	      const d = typeDecl(t.name);
184	      const members = d?.kind === 'EnumDecl' ? d.members : d?.kind === 'TypeDecl' && d.ctors.every((c) => !c.fields.length) ? d.ctors.map((c) => c.name) : null;
185	      if (!members) return `a field of type ${t.name} cannot be set by the map`;
186	      return members.includes(v) ? null : `${JSON.stringify(v)} is not a member of ${t.name}`;
187	    }
188	    default: return `a field of this type cannot be set by the map`;
189	  }
190	}
191	
192	/** The adapter's source: the map as data, and one method per member of Host with its parameters in order. */
193	function emit(map, host, machines, polyrun, kinds) {
194	  const members = [...host.members].filter(([n]) => !ADAPTER.includes(n));
195	  const methods = members.map(([n, params]) => `    ${n}: (${params.join(', ')}) => ${n in map.methods ? 'call' : 'query'}(${JSON.stringify(n)}, { ${params.join(', ')} }),`);
196	  return `// Generated by experiments/m3/adapter/generate.mjs from host.map.json (M3-4, S90). Do not edit.
197	// A fresh host over polyrun's kernel: a method dispatches one action to one instance, a query reads the
198	// instance's flat state, the network methods deliver messages one at a time (S89, S91), and the effect port
199	// lists the effects requested and completes one at a time with the outcome the caller gives (S95).
200	import { fileURLToPath } from 'node:url';
201	import { createRuntime } from ${JSON.stringify(polyrun)};
202	
203	const MAP = ${JSON.stringify(map, null, 2)};
204	const MACHINES = ${JSON.stringify(machines, null, 2)};
205	const KINDS = ${JSON.stringify(kinds)};
206	const at = (rel) => fileURLToPath(new URL(rel, import.meta.url));
207	const ARG = /^\\$arg:(.+)$/;
208	
209	export default async function createHost() {
210	  const outcomes = new Map();
211	  const rt = await createRuntime({
212	    store: { sqlite: ':memory:' },
213	    machines: MACHINES.map((m) => ({ machineId: m.machineId, module: at(m.module), contract: at(m.contract), ...(m.effects ? { effects: { mapper: at(m.effects.mapper), manifest: at(m.effects.manifest) } } : {}) })),
214	    // An effect's handler does what the caller of completeEffect said: it returns for ok, and throws a permanent
215	    // failure for failed, which polyrun completes with the effect's failed action at once.
216	    handlers: Object.fromEntries(KINDS.map((k) => [k, (_payload, intentId) => {
217	      if (outcomes.get(intentId) === 'ok') return {};
218	      const e = new Error('failed');
219	      e.permanent = true;
220	      throw e;
221	    }])),
222	  });
223	  let n = 0;
224	  const actionId = () => \`host-\${++n}\`;
225	  // An instance starts in its machine's initial state, with the map's values in place (as a configuration's, PS13.1).
226	  const make = async (id, spec) => {
227	    await rt.create(spec.machine, id);
228	    if (spec.init && Object.keys(spec.init).length) {
229	      const inst = await rt.store.getInstance(id);
230	      rt.store.db.prepare('UPDATE pr_instance SET state = ? WHERE instance_id = ?').run(JSON.stringify({ ...inst.state, ...spec.init }), id);
231	    }
232	  };
233	  for (const [name, spec] of Object.entries(MAP.instances)) if (spec.createdBy === undefined) await make(name, spec);
234	  // An instance named by an argument must be one created with the host, of the machine the map names.
235	  const idOf = (spec, args) => {
236	    if (ARG.test(spec.instance)) {
237	      const id = String(args[ARG.exec(spec.instance)[1]]);
238	      const inst = MAP.instances[id];
239	      return inst && inst.createdBy === undefined && inst.machine === spec.machine ? id : null;
240	    }
241	    return spec.key === undefined ? spec.instance : String(args[ARG.exec(spec.key)[1]]);
242	  };
243	  const valueOf = (v, args) => (typeof v === 'string' && ARG.test(v) ? args[ARG.exec(v)[1]] : v);
244	  const call = async (name, args) => {
245	    const spec = MAP.methods[name];
246	    const id = idOf(spec, args);
247	    const family = MAP.instances[spec.instance];
248	    const created = id !== null && family?.createdBy === name && !(await rt.store.getInstance(id));
249	    if (created) await make(id, family);
250	    if (id === null || !(await rt.store.getInstance(id))) return spec.returns === 'nothing' ? undefined : spec.returns === 'state' ? null : { ok: false, reason: 'unknown' };
251	    const data = Object.fromEntries(Object.entries(spec.params ?? {}).map(([p, v]) => [p, valueOf(v, args)]));
252	    const r = await rt.dispatch(id, spec.action, data, actionId());
253	    // A refused command changes nothing, so a creating command that is refused leaves no instance: a strict
254	    // domain refuses it before the handler, with the instance already made (PT3.4, M3-6).
255	    const purged = created && r.stepKind !== 'accepted';
256	    if (purged) await rt.store.purgeInstance(id);
257	    if (spec.returns === 'nothing') return undefined;
258	    // A purged instance has no state, as a query of an id never created answers null.
259	    if (spec.returns === 'state' && purged) return null;
260	    if (spec.returns === 'state') return (await rt.getState(id)).state;
261	    return r.stepKind === 'accepted' ? { ok: true } : { ok: false, reason: r.rejectReason ?? r.stepKind };
262	  };
263	  const query = async (name, args) => {
264	    const spec = MAP.queries[name];
265	    const id = idOf(spec, args);
266	    const inst = id === null ? null : await rt.getState(id).catch(() => null);
267	    if (!inst) return null;
268	    return Object.fromEntries(Object.entries(spec.fields).map(([out, f]) => [out, inst.state[f]]));
269	  };
270	  const inFlight = async () => (await rt.workers.pendingMessages()).map(({ id, from, to, action, data }) => ({ id, from, to, action, data }));
271	  // polyrun runs one claimed effect with its worker's own step (_runEffect), so the completion, its journal entry
272	  // and its deduplication are the engine's, not the adapter's.
273	  const pendingEffects = async () => rt.store.db.prepare("SELECT intent_id, instance_id, kind, payload FROM pr_outbox WHERE kind <> 'sendTo' AND status = 'pending' ORDER BY intent_id").all().map((r) => ({ id: r.intent_id, from: r.instance_id, kind: r.kind, data: JSON.parse(r.payload) ?? {} }));
274	  const completeEffect = async (id, outcome) => {
275	    if (outcome !== 'ok' && outcome !== 'failed') throw new Error("completeEffect: the outcome is 'ok' or 'failed', not " + JSON.stringify(outcome));
276	    const row = rt.store.db.prepare("SELECT * FROM pr_outbox WHERE intent_id = ? AND kind <> 'sendTo' AND status = 'pending'").get(id);
277	    if (!row) throw new Error('no effect ' + id + ' is pending');
278	    rt.store.db.prepare("UPDATE pr_outbox SET status = 'inflight', claimed_until = ? WHERE intent_id = ?").run(rt.now() + 60000, id);
279	    outcomes.set(id, outcome);
280	    await rt.workers._runEffect({ ...row, payload: JSON.parse(row.payload) }, rt.now());
281	  };
282	  return {
283	    pendingEffects,
284	    completeEffect,
285	    inFlight,
286	    async deliver(id) {
287	      if (!(await rt.workers.deliverMessage(id))) throw new Error(\`no message \${id} in transit\`);
288	    },
289	    async deliverAll() {
290	      // A bound, so a system that sends forever fails here instead of hanging the test.
291	      for (let i = 0; i < 10000; i++) if (!(await rt.workers.tickMessages())) return;
292	      throw new Error('deliverAll: messages still in transit after 10000 rounds');
293	    },
294	${methods.join('\n')}
295	    // Not members of any Host (the generator refuses them): __dispose releases the store, and __state gives every
296	    // instance's state, which O3's generator uses to tell apart states the interface shows alike.
297	    __dispose: () => rt.close(),
298	    __state: async () => rt.store.db.prepare('SELECT instance_id, state FROM pr_instance ORDER BY instance_id').all().map((r) => [r.instance_id, r.state]),
299	    // __snapshot and __restore copy every table of the store and the action-id counter, so O3's generator can
300	    // try each step from one state without replaying the path to it. O3's traces are replayed from a fresh host
301	    // by the controls, which would show any difference.
302	    __snapshot: async () => {
303	      const tables = rt.store.db.prepare("SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%' ORDER BY name").all().map((r) => r.name);
304	      return { n, rows: Object.fromEntries(tables.map((t) => [t, rt.store.db.prepare('SELECT rowid AS __rowid, * FROM ' + t).all()])) };
305	    },
306	    __restore: async (snap) => {
307	      for (const [t, rows] of Object.entries(snap.rows)) {
308	        rt.store.db.prepare('DELETE FROM ' + t).run();
309	        for (const r of rows) {
310	          const cols = Object.keys(r).filter((c) => c !== '__rowid');
311	          rt.store.db.prepare('INSERT INTO ' + t + ' (rowid, ' + cols.join(', ') + ') VALUES (?, ' + cols.map(() => '?').join(', ') + ')').run(r.__rowid, ...cols.map((c) => r[c]));
312	        }
313	      }
314	      n = snap.n;
315	      outcomes.clear();
316	    },
317	  };
318	}
319	`;
320	}
321	
322	/**
323	 * Validates and generates. Returns { errors } on a failed build, with nothing written; else { files }, the
324	 * paths written under `out`.
325	 */
326	export function generate({ mapFile, hostFile, moduleFile, out, polyrun = '@cognitive-fab/polygraph/polyrun/src/index.mjs' }) {
327	  let map;
328	  try { map = JSON.parse(readFileSync(mapFile, 'utf8')); } catch (e) { return { errors: [`host.map.json does not parse: ${e.message}`] }; }
329	  const host = readHost(readFileSync(hostFile, 'utf8'), hostFile);
330	  const loaded = loadModule(moduleFile);
331	  if (loaded.errors.length) return { errors: loaded.errors };
332	  const errors = validate(map, host, loaded.module);
333	  if (errors.length) return { errors };
334	  const machines = [];
335	  const lowered = [];
336	  const kinds = new Set();
337	  for (const machine of loaded.checked.machines.keys()) {
338	    const r = lowerMachine(loaded.module, loaded.checked, machine);
339	    if (!r.lowered) return { errors: r.diagnostics.map((d) => `${machine} does not lower: ${d.code} ${d.message}`) };
340	    lowered.push([machine, r.lowered.files]);
341	    if (r.lowered.files['effects.manifest.json']) for (const k of Object.keys(JSON.parse(r.lowered.files['effects.manifest.json']).effects ?? {})) kinds.add(k);
342	  }
343	  rmSync(join(out, 'build'), { recursive: true, force: true });
344	  const files = [];
345	  for (const [machine, fs] of lowered) {
346	    const rel = `build/${loaded.module.name}.${machine}`;
347	    mkdirSync(join(out, rel), { recursive: true });
348	    for (const [f, text] of Object.entries(fs)) { writeFileSync(join(out, rel, f), text); files.push(`${rel}/${f}`); }
349	    machines.push({ machineId: machine, module: `./${rel}/next.cjs`, contract: `./${rel}/contract.json`, ...(fs['effects.cjs'] ? { effects: { mapper: `./${rel}/effects.cjs`, manifest: `./${rel}/effects.manifest.json` } } : {}) });
350	  }
351	  writeFileSync(join(out, 'host.gen.ts'), emit(map, host, machines, polyrun, [...kinds].sort()));
352	  files.push('host.gen.ts');
353	  return { files };
354	}
355	
356	const flag = (name) => { const i = process.argv.indexOf(`--${name}`); return i > 0 ? process.argv[i + 1] : undefined; };
357	if (process.argv[1] && pathToFileURL(resolve(process.argv[1])).href === import.meta.url) {
358	  const [mapFile, hostFile, moduleFile, out, polyrun] = ['map', 'host', 'module', 'out', 'polyrun'].map(flag);
359	  if (!mapFile || !hostFile || !moduleFile || !out) {
360	    console.error(`usage: node ${basename(process.argv[1])} --map host.map.json --host host.ts --module <file.poly|file.ts> --out <dir>`);
361	    process.exit(64);
362	  }
363	  mkdirSync(out, { recursive: true });
364	  const r = generate({ mapFile, hostFile, moduleFile, out, ...(polyrun ? { polyrun } : {}) });
365	  if (r.errors) {
366	    console.error(`host.map.json: failed build (S90)\n${r.errors.map((e) => `  ${e}`).join('\n')}`);
367	    process.exit(1);
368	  }
369	  console.log(`wrote ${r.files.length} files to ${out}`);
370	}
