test('one write per grant', async () => {
  const h = await fresh();
  await h.acquire('c0');
  await h.deliverAll();
  assert.deepEqual(await h.write('c0'), { ok: true });
  await h.deliverAll();
  assert.deepEqual(await h.write('c0'), { ok: true });
  const w = (await h.inFlight())[0];
  await h.deliver(w.id);
  const reply = (await h.inFlight())[0];
  assert.equal(reply.action, 'WriteRefused');
  await h.deliverAll();
  assert.deepEqual(await h.lease(), { holder: 'c0', token: 1, writes: 1 });
  assert.deepEqual(await h.client('c0'), { status: 'holding', token: 1, writing: false });
  await h.release('c0');
  await h.acquire('c1');
  await h.deliverAll();
  await h.write('c1');
  await h.deliverAll();
  assert.deepEqual(await h.lease(), { holder: 'c1', token: 2, writes: 2 });
  h.__dispose();
});

